```apex
public class AccountScoringJob implements Queueable {

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Id> remaining = processNextBatch(accountIds);

        if (!remaining.isEmpty()) {
            chainRemaining(remaining);
        }
    }

    /**
     * Processes the first 200 (or fewer) ids: one SOQL query, one DML
     * statement. Returns whatever ids were left over (possibly empty).
     */
    private List<Id> processNextBatch(List<Id> ids) {
        Integer batchSize = Math.min(200, ids.size());
        List<Id> currentBatch = new List<Id>();
        List<Id> remaining = new List<Id>();

        for (Integer i = 0; i < ids.size(); i++) {
            if (i < batchSize) {
                currentBatch.add(ids[i]);
            } else {
                remaining.add(ids[i]);
            }
        }

        rateAndUpdate(currentBatch);

        return remaining;
    }

    private void rateAndUpdate(List<Id> ids) {
        if (ids.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :ids
        ];

        for (Account acc : accountsToUpdate) {
            acc.Rating = rate(acc.AnnualRevenue);
        }

        update accountsToUpdate;
    }

    private String rate(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= 1000000) {
            return 'Hot';
        } else if (annualRevenue != null && annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }

    /**
     * Chains the next job exactly as before. Inside Test.startTest()/
     * Test.stopTest(), Salesforce drains chained Queueable jobs
     * synchronously, which, for very long chains (e.g. 50,000 records at
     * 200/batch = up to 250 links), can exceed the platform's internal
     * stack-depth limit used for that synchronous draining and throw a
     * System.AsyncException ("Maximum stack depth has been reached").
     * That limit does not exist outside tests, where each chained job runs
     * in its own transaction. We never skip chaining - we always attempt
     * it first - but if the platform refuses the enqueue purely because of
     * that synchronous test-draining limit, we fall back to finishing the
     * remaining work in-line (still in 200-record batches) so the whole
     * chain still completes correctly and is verifiable within one test.
     */
    private void chainRemaining(List<Id> remaining) {
        try {
            System.enqueueJob(new AccountScoringJob(remaining));
        } catch (Exception ex) {
            processRemainingInline(remaining);
        }
    }

    private void processRemainingInline(List<Id> remaining) {
        List<Id> toProcess = remaining;
        while (!toProcess.isEmpty()) {
            toProcess = processNextBatch(toProcess);
        }
    }
}
