/**
 * Sends renewal-reminder emails to opportunity owners.
 *
 * Messaging.sendEmail can only be invoked a maximum of 10 times per Apex
 * transaction (this is independent of how many messages are passed to each
 * call). Since this method can receive up to 200 opportunities in a single
 * call, emails are batched so that at most 10 Messaging.sendEmail
 * invocations occur, each carrying a chunk of messages. Each call uses
 * allOrNone = false, so Salesforce still reports per-message success or
 * failure via Messaging.SendEmailResult, meaning a single bad message does
 * not prevent the rest of the messages in its batch (or other batches)
 * from being sent.
 */
public with sharing class RenewalReminderService {

    // Hard governor limit: Messaging.sendEmail invocations per transaction.
    private static final Integer MAX_SEND_EMAIL_INVOCATIONS = 10;

    public static Integer sendReminders(List<Id> opportunityIds) {
        Integer sentCount = 0;

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return sentCount;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opportunities) {
            if (opp.OwnerId == null) {
                continue;
            }

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);

            String closeDateStr = opp.CloseDate != null
                ? opp.CloseDate.format()
                : 'an unspecified date';

            email.setPlainTextBody(
                'This is a reminder that the opportunity "' + opp.Name +
                '" has a renewal due with a close date of ' + closeDateStr +
                '. Please review and take any necessary action.'
            );

            messages.add(email);
        }

        if (messages.isEmpty()) {
            return sentCount;
        }

        // Determine the smallest batch size that keeps the number of
        // Messaging.sendEmail invocations within the governor limit.
        Integer batchSize = (Integer) Math.ceil(
            (Decimal) messages.size() / MAX_SEND_EMAIL_INVOCATIONS
        );
        if (batchSize < 1) {
            batchSize = 1;
        }

        for (Integer startIndex = 0; startIndex < messages.size(); startIndex += batchSize) {
            Integer endIndex = Math.min(startIndex + batchSize, messages.size());
            List<Messaging.SingleEmailMessage> batch = new List<Messaging.SingleEmailMessage>();
            for (Integer i = startIndex; i < endIndex; i++) {
                batch.add(messages[i]);
            }

            try {
                Messaging.SendEmailResult[] results = Messaging.sendEmail(batch, false);

                if (results != null) {
                    for (Messaging.SendEmailResult result : results) {
                        if (result.isSuccess()) {
                            sentCount++;
                        } else {
                            System.debug(
                                LoggingLevel.ERROR,
                                'RenewalReminderService: failed to send a reminder - ' +
                                result.getErrors()
                            );
                        }
                    }
                }
            } catch (Exception ex) {
                // Swallow so one batch failure doesn't stop reminders for other batches.
                System.debug(
                    LoggingLevel.ERROR,
                    'RenewalReminderService: batch send failed - ' + ex.getMessage()
                );
            }
        }

        return sentCount;
    }
}
