/**
 * HouseholdService
 *
 * Creates a single NPSP Household Account for a family of new Contacts,
 * relying on NPSP's automatic household creation/naming logic.
 */
public with sharing class HouseholdService {

    public class HouseholdServiceException extends Exception {}

    /**
     * Inserts the given Contacts so that they all belong to ONE new NPSP
     * Household Account. The first Contact in the list becomes the
     * household's primary contact. Returns the new Household Account's Id.
     *
     * @param members List of new Contacts (no Id, no AccountId set).
     * @return Id of the newly created Household Account.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty.');
        }

        // Insert the first Contact on its own. With no AccountId set, NPSP's
        // TDTM Household trigger logic will create exactly one new
        // Household Account for it, apply the correct Household Account
        // record type, and generate the name/greetings automatically.
        Contact primaryContact = members[0];
        primaryContact.AccountId = null;
        insert primaryContact;

        // Re-query to pick up the AccountId NPSP assigned during insert.
        Contact insertedPrimary = [
            SELECT Id, AccountId
            FROM Contact
            WHERE Id = :primaryContact.Id
            LIMIT 1
        ];
        Id householdAccountId = insertedPrimary.AccountId;

        if (householdAccountId == null) {
            throw new HouseholdServiceException(
                'NPSP did not create a Household Account for the primary contact.'
            );
        }

        // Attach all remaining contacts to the SAME household account before
        // inserting, so NPSP does not spin up additional household accounts
        // for them.
        List<Contact> remaining = new List<Contact>();
        for (Integer i = 1; i < members.size(); i++) {
            Contact c = members[i];
            c.AccountId = householdAccountId;
            remaining.add(c);
        }
        if (!remaining.isEmpty()) {
            insert remaining;
        }

        // Set the household's primary contact.
        Account household = new Account(
            Id = householdAccountId,
            npe01__One2OneContact__c = insertedPrimary.Id
        );
        update household;

        return householdAccountId;
    }
}
