        // ---- Build / reconcile Partial Soft Credits ----
        List<npsp__Partial_Soft_Credit__c> pscToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscToUpdate = new List<npsp__Partial_Soft_Credit__c>();
        Set<String> processedPairs = new Set<String>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + ':' + req.contactId;
            if (processedPairs.contains(key)) {
                continue; // requests are expected to be unique per opp/contact pair, guard just in case
            }
            processedPairs.add(key);

            Id ocrId;
            OpportunityContactRole existingOcr = ocrMap.get(key);
            if (existingOcr != null) {
                ocrId = existingOcr.Id;
            } else {
                ocrId = newOcrByKey.get(key).Id;
            }

            npsp__Partial_Soft_Credit__c existingPsc = pscMap.get(key);
            if (existingPsc != null) {
                existingPsc.npsp__Amount__c = req.amount;
                existingPsc.npsp__Role_Name__c = req.role;
                existingPsc.npsp__Contact_Role_ID__c = ocrId;
                pscToUpdate.add(existingPsc);
            } else {
                pscToInsert.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = ocrId
                ));
            }
        }

        if (!pscToInsert.isEmpty()) {
            insert pscToInsert; // DML 3
        }
        if (!pscToUpdate.isEmpty()) {
            update pscToUpdate; // DML 4
        }
    }
