```apex
/**
 * Service class used by mass-edit UIs to determine which of a given set of
 * record Ids the running user is actually allowed to edit, taking into
 * account object permissions, field level security on access (not fields),
 * ownership, sharing rules, role hierarchy, and View All / Modify All.
 *
 * This is achieved by querying the UserRecordAccess object, which Salesforce
 * maintains and which already folds together every one of those factors in
 * its HasEditAccess field.
 */
public with sharing class RecordAccessService {

    // UserRecordAccess queries that filter on RecordId support at most 200
    // Ids per query. We chunk the input accordingly to stay well within
    // governor limits (2,000 Ids / 200 per chunk = 10 queries, well under
    // the 20 query budget we are given for this method).
    private static final Integer CHUNK_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        Id currentUserId = UserInfo.getUserId();

        List<Id> idList = new List<Id>(recordIds);
        Integer total = idList.size();

        for (Integer startIndex = 0; startIndex < total; startIndex += CHUNK_SIZE) {
            Integer stopIndex = Math.min(startIndex + CHUNK_SIZE, total);
            List<Id> chunk = new List<Id>();
            for (Integer i = startIndex; i < stopIndex; i++) {
                chunk.add(idList[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess) {
                    result.add(access.RecordId);
                }
            }
        }

        return result;
    }
}
